import React, { useState, useEffect } from "react";
import { Box, Typography, Button } from "@mui/material";

const backgroundImages = [
  "/Background19.jpg",
  "/Background20.jpg",
  "/Background21.jpg",
  "/Background22.jpg",
];

export default function HomePage() {
  const [currentBackground, setCurrentBackground] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentBackground((prev) => (prev + 1) % backgroundImages.length);
    }, 3000); // Background changes every 3 seconds

    return () => clearInterval(interval);
  }, []);

  return (
    <Box
      sx={{
        padding: { xs: 2, sm: 4 },
        textAlign: "center",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        backgroundImage: `url(${backgroundImages[currentBackground]})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        transition: "background-image 0.8s ease-in-out", // Smooth transition between images
      }}
    >
      <Typography
        variant="h3"
        gutterBottom
        sx={{
          fontWeight: "bold",
          color: "#b56f76",
          fontSize: { xs: "2rem", sm: "3rem" }, // Responsive font size
        }}
      >
        EVERPLAN
      </Typography>
      <Typography
        variant="h5"
        gutterBottom
        sx={{
          fontStyle: "italic",
          color: "#6B4F4F",
          fontSize: { xs: "1.2rem", sm: "1.5rem" }, // Adjusts for smaller screens
        }}
      >
        Plan, Book, Celebrate—It’s That Easy!
      </Typography>

      <Button
        variant="contained"
        sx={{
          marginTop: 2,
          padding: "10px 20px",
          fontSize: "1rem",
          borderRadius: 2,
          width: "200px", // Smaller button width
          backgroundColor: "#F7C5AD", // Custom button color
          color: "#fff", // White text color for contrast
          "&:hover": {
            backgroundColor: "#F7C5AD", // Slightly darker shade on hover
          },
        }}
        href="#venues"
      >
        Book Now
      </Button>
    </Box>
  );
}
